// Shared unit cubes, assembled into expressive models without per-mob draw calls.
// Parts: center xyz, size xyz, color, optional animated joint, pivot height.
export const MAX_CHARACTER_PARTS = 48;
export function characterParts(kind, id = 0) {
  const parts = [];
  const add = (x, y, z, sx, sy, sz, c, j = null, pivot = 0) =>
    parts.push([x, y, z, sx, sy, sz, c, j, pivot]);
  if (kind === 'companion') {
    add(0, 0.5, 0, 0.48, 0.42, 0.84, '#a9875b');
    add(0, 0.65, -0.1, 0.45, 0.18, 0.52, '#795d40');
    add(0, 0.7, 0.45, 0.38, 0.37, 0.38, '#ba996d');
    add(0, 0.59, 0.7, 0.27, 0.19, 0.27, '#e1d1b3');
    add(0, 0.63, 0.85, 0.18, 0.1, 0.05, '#302c29');
    add(0, 0.72, 0.26, 0.43, 0.1, 0.42, '#4db6b4');
    add(0, 0.57, 0.49, 0.075, 0.08, 0.025, '#e0bd66');
    for (const side of [-1, 1]) {
      add(side * 0.13, 0.96, 0.41, 0.13, 0.24, 0.15, '#795d40');
      add(side * 0.13, 0.97, 0.492, 0.064, 0.14, 0.017, '#d0a69b');
      add(side * 0.12, 0.77, 0.645, 0.085, 0.084, 0.017, '#302c29', 'eye');
      add(side * 0.13, 0.79, 0.659, 0.027, 0.027, 0.012, '#fff7e6', 'pupil');
    }
    add(0, 0.54, 0.71, 0.21, 0.045, 0.2, '#665142');
    add(0, 0.5, 0.76, 0.09, 0.075, 0.12, '#cd8787');
    add(0, 0.66, -0.56, 0.13, 0.16, 0.42, '#ad8c5f', 'tail');
    add(0, 0.68, -0.78, 0.14, 0.16, 0.12, '#e4d2b6', 'tail');
    for (const [x, z, j] of [
      [-0.16, -0.28, 'legL'],
      [0.16, -0.28, 'legR'],
      [-0.16, 0.28, 'legR'],
      [0.16, 0.28, 'legL'],
    ]) {
      add(x, 0.25, z, 0.12, 0.4, 0.14, '#b39770', j, 0.44);
      add(x, 0.065, z + 0.025, 0.14, 0.13, 0.21, '#e4d5ba', j, 0.44);
    }
  } else if (kind === 'sheep') {
    const wool = ['#eee6d5', '#d5cab4', '#b6a79a'][id % 3];
    add(0, 0.66, 0, 0.8, 0.6, 1.05, wool);
    add(0, 0.96, -0.05, 0.68, 0.12, 0.88, '#f4efdd');
    add(0, 0.84, 0.61, 0.42, 0.44, 0.4, '#8e7b68');
    add(0, 1.06, 0.57, 0.48, 0.13, 0.35, wool);
    add(0, 0.73, 0.84, 0.31, 0.18, 0.15, '#b8a592');
    add(0, 0.76, 0.927, 0.12, 0.07, 0.012, '#57443d');
    for (const side of [-1, 1]) {
      add(side * 0.3, 0.88, 0.6, 0.2, 0.14, 0.16, wool);
      add(side * 0.34, 0.885, 0.69, 0.11, 0.07, 0.022, '#bd8a87');
      add(side * 0.13, 0.92, 0.815, 0.1, 0.1, 0.016, '#fff9ed');
      add(side * 0.14, 0.92, 0.827, 0.045, 0.064, 0.012, '#282a2c', 'eye');
    }
    add(0, 0.68, -0.59, 0.17, 0.2, 0.2, wool);
    for (const [x, z, j] of [
      [-0.25, -0.34, 'legL'],
      [0.25, -0.34, 'legR'],
      [-0.25, 0.34, 'legR'],
      [0.25, 0.34, 'legL'],
    ]) {
      add(x, 0.27, z, 0.16, 0.48, 0.16, '#9c8872', j, 0.5);
      add(x, 0.055, z, 0.18, 0.11, 0.2, '#514944', j, 0.5);
    }
  } else {
    const pip = kind === 'companion',
      ember = kind === 'ember',
      skin = ember ? '#df784e' : pip ? '#dab997' : ['#b88061', '#d7ac82', '#8e624d'][id % 3],
      coat = pip ? '#438e91' : ember ? '#872f3a' : ['#70547f', '#526478', '#866144'][id % 3];
    add(0, 1.03, 0, 0.54, 0.66, 0.32, coat);
    add(0, 0.73, 0, 0.56, 0.1, 0.34, '#493e3c');
    add(0.12, 0.74, 0.186, 0.1, 0.08, 0.032, '#d7b775');
    for (const [side, j] of [
      [-1, 'legL'],
      [1, 'legR'],
    ]) {
      add(side * 0.15, 0.38, 0, 0.23, 0.65, 0.26, ember ? '#572d35' : '#36444c', j, 0.7);
      add(side * 0.15, 0.09, 0.035, 0.25, 0.18, 0.33, '#343737', j, 0.7);
    }
    for (const [side, j] of [
      [-1, 'armL'],
      [1, 'armR'],
    ]) {
      add(side * 0.385, 1.1, 0, 0.2, 0.51, 0.26, coat, j, 1.34);
      add(side * 0.385, 0.8, 0, 0.18, 0.15, 0.23, skin, j, 1.34);
      add(
        side * 0.385,
        1.34,
        0,
        0.25,
        0.14,
        0.3,
        pip ? '#aec4b6' : ember ? '#ad5147' : '#8c9498',
        j,
        1.34,
      );
    }
    add(0, 1.57, 0, 0.44, 0.44, 0.42, skin, 'head');
    const hair = ember ? '#54252d' : pip ? '#694e38' : '#342e30';
    add(0, 1.8, 0, 0.48, 0.11, 0.46, hair, 'head');
    add(0, 1.58, -0.205, 0.46, 0.35, 0.055, hair, 'head');
    add(-0.205, 1.68, 0.03, 0.055, 0.21, 0.37, hair, 'head');
    add(0.205, 1.72, 0.01, 0.055, 0.14, 0.37, hair, 'head');
    for (const side of [-1, 1]) {
      add(side * 0.1, 1.61, 0.218, 0.108, 0.079, 0.024, ember ? '#ffd992' : '#fffbeb', 'eye');
      add(side * 0.09, 1.61, 0.235, 0.04, 0.064, 0.018, ember ? '#ff692b' : '#284449', 'pupil');
      add(side * 0.1, 1.68, 0.226, 0.12, 0.024, 0.025, hair, 'head');
      add(side * 0.237, 1.57, 0, 0.048, 0.1, 0.1, skin, 'head');
    }
    add(0, 1.55, 0.24, 0.06, 0.075, 0.06, skin, 'head');
    add(0, 1.45, 0.22, 0.13, 0.022, 0.025, '#825342', 'head');
    if (pip) {
      add(0, 1.35, 0.03, 0.58, 0.12, 0.39, '#d7ac54');
      add(-0.14, 1.16, 0.195, 0.13, 0.3, 0.045, '#e1b760');
      add(0, 1.06, -0.26, 0.39, 0.46, 0.21, '#9d7250');
      add(0, 1.31, -0.27, 0.41, 0.09, 0.24, '#cda370');
      add(0.13, 1.13, 0.17, 0.12, 0.17, 0.04, '#a7d1bb');
      add(0, 1.77, 0.18, 0.47, 0.08, 0.11, '#be9b59', 'head');
      for (const side of [-1, 1]) {
        add(side * 0.12, 1.77, 0.249, 0.17, 0.13, 0.035, '#ddc782', 'head');
        add(side * 0.12, 1.77, 0.272, 0.11, 0.077, 0.018, '#73cbd1', 'head');
      }
    } else if (ember) {
      for (const side of [-1, 1]) {
        add(side * 0.22, 1.9, -0.04, 0.12, 0.22, 0.15, '#f0c69c', 'head');
        add(side * 0.28, 1.99, -0.04, 0.11, 0.09, 0.13, '#dc935d', 'head');
      }
      add(0, 1.07, 0.175, 0.09, 0.44, 0.045, '#f0a54c');
      add(0, 1.06, -0.2, 0.18, 0.42, 0.1, '#562b37');
    } else {
      add(0, 1.1, 0.18, 0.38, 0.36, 0.07, '#889194');
      add(0, 1.11, 0.222, 0.1, 0.18, 0.02, '#b7c2b7');
      add(0, 1.37, 0, 0.57, 0.1, 0.37, '#ab7963');
      if (kind !== 'player') {
        add(0.385, 0.72, 0.04, 0.12, 0.13, 0.15, '#59615e', 'armR', 1.34);
        add(0.385, 0.44, 0.04, 0.09, 0.44, 0.055, '#abbfc2', 'armR', 1.34);
      }
    }
  }
  return parts;
}
